task binary_search(arr: seq, x: int) returns (r: bool)
  requires len(arr) >= 0
  ensures r == (x in arr)
{
  var lo: int := 0;
  var hi: int := len(arr) - 1;
  while lo <= hi
    invariant 0 <= lo and lo <= hi and hi < len(arr)
    invariant forall i in [lo, hi) . arr[i] <= arr[i + 1]
    decreases hi - lo
  {
    var mid: int := (lo + hi) / 2;
    if arr[mid] == x {
      r := true;
      return;
    }
    if arr[mid] < x {
      lo := mid + 1;
    } else {
      hi := mid - 1;
    }
  }
  r := false;
}
